-- Changelog: servicedesk-tabs zonder schakelbalk + uitvoering in het Servicedesk-blok.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-28','verbeterd','Servicedesk','Bestanden en Meerwerk weer als eigen tab, en in één oogopslag wie er komt',
   'Op een servicedeskbon staan Bestanden en Meerwerk weer als eigen tab in de zijbalk, zonder schakelaar bovenaan de pagina. In het Servicedesk-blok zie je nu in het midden welke medewerkers en onderaannemers zijn ingepland of opgedragen, en op welke dag. De tijd per fase staat voortaan onder het mandaat.');
